import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long mergeCount(long[] a, long[] tmp, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) / 2;
        long inv = mergeCount(a, tmp, lo, mid) + mergeCount(a, tmp, mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                tmp[k++] = a[j++];
                inv += mid - i;
            }
        }
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi) tmp[k++] = a[j++];
        for (int t = lo; t < hi; t++) a[t] = tmp[t];
        return inv;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long[] tmp = new long[(int) n];
        System.out.println(mergeCount(a, tmp, 0, (int) n));
    }
}
